  }, "\uC548\uCCA0\uC218\uAC00 \uBB34\uB98E\uD30D\uB3C4\uC0AC\uC5D0 \uB098\uC640\uC11C \uD588\uB358 \uB9D0"), "\uB3C4 \uBE44\uC2B7\uD558\uAC8C \uC77D\uD78C\uB2E4."), mdx("blockquote", null, mdx("p", {
    parentName: "blockquote"
  }, "\uD6A8\uC728\uC131\uC774\uB77C\uB294 \uC785\uC7A5\uC5D0\uC11C \uBCF4\uBA74 \uC800\uB294 \uC6B0\uB9AC\uB098\uB77C\uC5D0\uC11C \uAC00\uC7A5 \uBE44\uD6A8\uC728\uC801\uC778 \uC0AC\uB78C\uC774\uC8E0. \uC758\uC0AC\uB85C\uC11C\uC758 \uADF8 \uC0DD\uD65C 14\uB144 \uB3D9\uC548 \uD588\uB358 \uAC8C CEO \uD558\uBA74\uC11C \uAC70\uC758 \uC4F8\uBAA8\uAC00 \uC5C6\uC5B4\uC84C\uACE0\uC694, \uD504\uB85C\uADF8\uB798\uBC0D\uD560 \uB54C \uADF8\uAC83\uB3C4 CEO \uD560 \uB54C\uB294 \uC4F8\uBAA8\uAC00 \uC5C6\uC5B4\uC9C0\uACE0\uC694. \uADF8\uB7EC\uB2C8\uAE4C \uD6A8\uC728\uC801\uC778 \uC778\uC0DD\uC774 \uC131\uACF5\uC774\uB77C\uACE0 \uD558\uBA74 \uC800 \uAC19\uC740 \uC0AC\uB78C \uC778\uC0DD\uC740 \uC2E4\uD328\uB77C\uACE0 \uBD10\uC57C \uB418\uAC70\uB4E0\uC694. \uADF8\uB798\uC11C \uC790\uAE30\uAC00 \uC815\uB9D0\uB85C \uB9DE\uB294 \uBD84\uC57C\uB97C \uCC3E\uAE30 \uC704\uD574\uC11C \uC4F0\uB294 \uC2DC\uAC04\uC740 \uC800\uB294 \uAC12\uC9C4 \uC2DC\uAC04 \uAC19\uC544\uC694.")), mdx("p", null, "\uC0AC\uB78C\uC740 \uCC98\uC74C\uBD80\uD130 \uC790\uAE30\uAC00 \uBB34\uC5C7\uC5D0 \uB9DE\uB294\uC9C0 \uC54C \uC218 \uC5C6\uACE0, \uC5B4\uB5A4 \uC77C\uC774 \uC790\uAE30\uC5D0\uAC8C \uB9DE\uB294\uC9C0\uB294 \uD574\uBD10\uC57C \uC548\uB2E4. \uC758\uC0AC\uC5D0\uC11C \uBC31\uC2E0 \uAC1C\uBC1C\uC790\uB85C, CEO\uB85C, \uAD50\uC218\uB85C \uC790\uB9AC\uB97C \uC62E\uAE34 \uC2DC\uAC04\uC740 \uD6A8\uC728\uC758 \uAD00\uC810\uC5D0\uC11C \uC2E4\uD328\uCC98\uB7FC \uBCF4\uC774\uC9C0\uB9CC, \uC548\uCCA0\uC218\uC5D0\uAC8C \uADF8 \uC2DC\uAC04\uC740 \uC790\uAE30\uC5D0\uAC8C \uC5B4\uB5A4 \uC77C\uC774 \uB9DE\uB294\uC9C0\uB97C \uACC4\uC18D \uD655\uC778\uD55C \uC2DC\uAC04\uC774\uB2E4. \uB450 \uC0AC\uB78C\uC774 \uC5B8\uB7EC\uB2DD\uC744 \uD574\uC11C \uC800\uB807\uAC8C \uB418\uC5C8\uB098? \uADF8\uC800 \uC9C0\uAE08\uC758 \uC790\uAE30\uB97C \uC644\uC131\uBCF8\uC73C\uB85C \uB450\uC9C0 \uC54A\uC558\uC744 \uBFD0\uC774\uB77C\uACE0 \uC0DD\uAC01\uD55C\uB2E4."), mdx("p", null, mdx("a", {
    parentName: "p",
    "href": "https://maxkim-j.github.io/posts/why-dev"
  }, "\uB098\uB3C4 \uC778\uBB38\uD559 \uC804\uACF5\uC790\uC600\uACE0 \uC5D0\uB514\uD130\uAC00 \uB418\uACE0 \uC2F6\uC5C8\uB2E4\uAC00 2019\uB144\uC5D0 \uAC1C\uBC1C\uC790\uAC00 \uB3FC\uC11C 7\uB144\uC9F8 \uD558\uACE0 \uC788\uB2E4."), " \uADF8\uB54C \uBB34\uC2A8 \uBE44\uC7A5\uD55C \uACB0\uB2E8\uC744 \uD55C \uAC8C \uC544\uB2C8\uC5C8\uB2E4. \uC5D0\uB514\uD130\uB85C \uD68C\uC0AC\uC5D0 \uCDE8\uC9C1\uD558\uAE30\uAC00 \uB108\uBB34 \uC5B4\uB824\uC6E0\uACE0, \uC88B\uC544\uD558\uB294 \uC77C\uB85C \uB3C8\uC744 \uC801\uB2F9\uD788 \uBC84\uB294 \uBBF8\uB798\uBCF4\uB2E4 \uC801\uB2F9\uD788 \uD765\uBBF8\uAC00 \uC788\uB294 \uC77C\uB85C \uB3C8\uC744 \uB354 \uB9CE\uC774 \uBC84\uB294 \uBBF8\uB798\uAC00 \uB098\uC544 \uBCF4\uC600\uAE30 \uB54C\uBB38\uC774\uC5C8\uB2E4. \uC798 \uD480\uB838\uACE0 \uC6B4\uC774 \uC88B\uC558\uB2E4. \uAC1C\uBC1C\uC744 \uBC30\uC6B0\uB294 \uC77C\uC774 \uC0DD\uAC01\uD574\uBCF4\uBA74 \uADF8\uB807\uAC8C \uD798\uB4E4\uC9C0\uB294 \uC54A\uC558\uB2E4. \uB0B4\uAC00 \uADF8\uB3D9\uC548 \uACF5\uBD80\uD574\uC628 \uAC83\uACFC\uC758 \uACF5\uD1B5\uC810\uC744 \uC790\uAFB8 \uCC3E\uC544\uB0B4\uBA70 \uC774\uAC83\uB3C4 \uD560 \uB9CC\uD558\uB2E4\uACE0 \uB290\uB080 \uC2DC\uAC04\uC774\uC5C8\uB2E4."), mdx("p", null, "\uC9C0\uAE08\uC740 \uC5B8\uB7EC\uB2DD\uB9C8\uC800\uB3C4 \uAC12\uC774 \uC2F8\uB2E4. \uD604\uC7AC\uC5D0\uC11C \uC131\uCDE8\uD560\uB9CC\uD55C \uBAA9\uD45C\uB85C \uD5A5\uD558\uB294 \uACFC\uC815\uC740 AI\uB098 \uC815\uBCF4 \uC811\uADFC\uC131\uC774 \uB192\uC544\uC838\uC11C \uB9E4\uC6B0 \uC9E7\uC544\uC84C\uB2E4. \uAC1C\uBC1C\uC790\uAC00 \uD074\uB85C\uB4DC \uCF54\uB4DC \uAC19\uC740 \uB3C4\uAD6C\uB85C \uB204\uAD6C\uB098 \uCF54\uB529\uC744 \uD55C\uB2E4\uACE0 \uC88C\uC808\uD558\uB294 \uAC83\uB3C4 \uC720\uD589\uC774 \uC9C0\uB0AC\uB2E4. \uC790\uAE30\uAC00 \uAE30\uD68D\uC744 \uD55C\uB2E4\uBA74, \uB514\uC790\uC778\uC744 \uD55C\uB2E4\uBA74 \uC5B4\uB5BB\uAC8C \uB420\uC9C0 \uB108\uBB34 \uC27D\uAC8C \uC2DC\uC791\uD560 \uC218 \uC788\uB2E4. \uAC00\uBC29\uB048 \uAE34 \uC0AC\uB78C\uB4E4\uC758 \uC77C\uC774\uB77C\uACE0 \uC5EC\uACA8\uC9C0\uB358 \uBD84\uC790\uC0DD\uBB3C\uD559 \uC5F0\uAD6C, \uACE0\uC18C\uC7A5 \uC791\uC131, \uC138\uAE08 \uC2E0\uACE0\uB3C4 \uB9C8\uC74C\uB9CC \uBA39\uC73C\uBA74 \uD574\uBCFC \uC218 \uC788\uB2E4. \uC774\uC81C \uC5B8\uB7EC\uB2DD\uC740 \uADF8\uB0E5 \uD558\uBA74 \uB418\uB294 \uC77C\uC774 \uB410\uB2E4."), mdx("p", null, "\uC5B8\uB7EC\uB2DD\uC774\uB77C\uB294 \uB9D0 \uC790\uCCB4\uB97C \uC5B8\uB7EC\uB2DD\uD574\uC57C \uD560 \uB54C\uAC00 \uC27D\uAC8C\uB3C4 \uC654\uB2E4. \uC790\uAE30\uB97C \uB2E4 \uBC84\uB9AC\uACE0 \uB2E4\uC2DC \uBC30\uC6B0\uB77C\uB294 \uC870\uC5B8\uB3C4, \"\uB108\uBB34 \uC5D1\uC140 \uD321\uC158? \uC0AC\uC6A9 \uD558\uC9C0 \uB9C8\uC138\uC694.\" \uC5D0 \uB300\uD55C \uC870\uB871\uB3C4 \uADC0\uAE30\uC6B8\uC5EC \uB4E4\uC744 \uAC83\uC740 \uBABB \uB41C\uB2E4. \uC880 \uB354 \uB098\uC544\uAC00\uC11C \uBAA8\uB4E0 \uACFC\uC815\uACFC \uBAA9\uD45C\uB97C \uB2E4 \uAE54\uBCF4\uACE0 \uADF8\uB0E5 \uD574\uBCF4\uACE0 \uC2F6\uC5B4\uC838\uC57C \uD560 \uB54C\uAC00 \uC628 \uAC83 \uAC19\uB2E4."));
